import { Product } from '../model/models.js';

export function page(limit?: number) {
  let page = new Product().addAllColumns();
  let conditions = 0;
  if (limit !== undefined) {
    page = conditions === 0 ? page.gtPrice(limit) : page.andGtPrice(limit);
    conditions++;
  }
  if (limit !== undefined) {
    page = conditions === 0 ? page.ltPrice(limit) : page.andLtPrice(limit);
  }
  return page;
}

